const crypto = require('crypto');
const input = $input.first().json;
const correlationId = String(input.correlationId || input.metadata?.correlationId || $execution.id);
const webhookId = String(input.webhookId || `leadops-${correlationId}`).replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 200);
const event = {
  specVersion: '1.0',
  eventId: input.eventId || crypto.randomUUID(),
  eventType: input.eventType,
  occurredAt: input.occurredAt || new Date().toISOString(),
  source: input.source || 'n8n',
  organizationId: $env.LEADOPS_ORGANIZATION_ID,
  clientId: $env.LEADOPS_CLIENT_ID,
  workflow: { id: $workflow.id, name: $workflow.name },
  run: { id: $execution.id },
  data: input.data || {},
  metadata: { schemaVersion: '1.0', correlationId }
};
if (!event.eventType) throw new Error('eventType is required');
return [{ json: { event, webhookId } }];

const crypto = require('crypto');
const item = $input.first().json;
const secret = $env.LEADOPS_WEBHOOK_SECRET;
if (!secret) throw new Error('LEADOPS_WEBHOOK_SECRET is required');
const timestamp = String(Math.floor(Date.now() / 1000));
const rawBody = JSON.stringify(item.event);
const encoded = secret.startsWith('whsec_') ? secret.slice(6) : secret;
const signature = crypto.createHmac('sha256', Buffer.from(encoded, 'base64'))
  .update(`${item.webhookId}.${timestamp}.${rawBody}`)
  .digest('base64');
return [{ json: { rawBody, webhookId: item.webhookId, timestamp, signature: `v1,${signature}` } }];
